package br.com.social.post;import br.com.social.auth.*;import br.com.social.comment.*;import org.springframework.http.*;import org.springframework.messaging.simp.SimpMessagingTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class PostService{private final PostRepository posts;private final PostLikeRepository likes;private final CommentRepository comments;private final AppUserRepository users;private final SimpMessagingTemplate msg;public PostService(PostRepository p,PostLikeRepository l,CommentRepository c,AppUserRepository u,SimpMessagingTemplate m){posts=p;likes=l;comments=c;users=u;msg=m;}public record View(Long id,String authorEmail,String authorName,String content,java.time.LocalDateTime createdAt,boolean hidden,long likeCount,long commentCount,boolean likedByMe){}private View view(Post p,String me){return new View(p.getId(),p.getAuthorEmail(),p.getAuthorName(),p.getContent(),p.getCreatedAt(),p.isHidden(),likes.countByPostId(p.getId()),comments.countByPostId(p.getId()),likes.existsByPostIdAndUserEmail(p.getId(),me));}public List<View> feed(String me){return posts.findByHiddenFalseOrderByCreatedAtDesc().stream().map(p->view(p,me)).toList();}public List<View> mine(String me){return posts.findByAuthorEmailOrderByCreatedAtDesc(me).stream().map(p->view(p,me)).toList();}public List<View> admin(String me){return posts.findAllByOrderByCreatedAtDesc().stream().map(p->view(p,me)).toList();}public Post create(String content,String email){AppUser u=users.findByEmail(email).orElseThrow();Post p=posts.save(new Post(email,u.getName(),content));notify("POST_CREATED",p.getId());return p;}@Transactional public boolean toggleLike(Long id,String email){Post p=find(id);var old=likes.findByPostIdAndUserEmail(id,email);if(old.isPresent()){likes.delete(old.get());notify("LIKE_CHANGED",id);return false;}likes.save(new PostLike(id,email));notify("LIKE_CHANGED",id);return true;}public Post find(Long id){return posts.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Post não encontrado"));}@Transactional public void delete(Long id,String me,boolean admin){Post p=find(id);if(!admin&&!p.getAuthorEmail().equals(me))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Você só pode excluir seus posts");likes.deleteByPostId(id);comments.deleteByPostId(id);posts.delete(p);notify("POST_DELETED",id);}public Post moderate(Long id,boolean hidden){Post p=find(id);p.setHidden(hidden);p=posts.save(p);notify("POST_MODERATED",id);return p;}private void notify(String action,Long id){msg.convertAndSend("/topic/social",Map.of("action",action,"postId",id));}}
